// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testFuzz_property(uint256 v, uint256 v2) public {

        bool ok;
        try c.SetMinSum(v) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            uint256 m1 = c.MinSum();
            assertTrue(m1 == v);

            try c.SetMinSum(v2) {
                ok = true;
            } catch {
                ok = false;
            }
            if (ok) {
                uint256 m2 = c.MinSum();
                assertTrue(m2 == v2);
            } else {
                assertTrue(false);
            }
        } else {
            assertTrue(false);
        }
    }
}
